mapper.select:
/* isry.drmgs.stats.mapper.StatsDrmgsMapper.selectOccpAbilitStats */ SELECT TT1.CTPV_CD , TT2.CTPV_NM , TT3.SGG_CD , TT3.SGG_NM , TT1.INST_NO , TT1.INST_NM , COUNT(DISTINCT TT1.TRPR_INFO_NO) AS TRPR_CNT , COUNT(1) AS CASE_CNT , SUM(STG1_CNT) AS STG1_CNT , SUM(STG2_FNSH_CNT) AS STG2_FNSH_CNT , SUM(STG2_FAILR_CNT) AS STG2_FAILR_CNT , SUM(STG3_FNSH_CNT) AS STG3_FNSH_CNT , SUM(STG3_FAILR_CNT) AS STG3_FAILR_CNT , SUM(STG4_FNSH_CNT) AS STG4_FNSH_CNT , SUM(STG4_FAILR_CNT) AS STG4_FAILR_CNT , SUM(FOUND_CNT) AS FOUND_CNT , SUM(JOB_CNT) AS JOB_CNT , SUM(JOB_CNT2) AS JOB_CNT2 , SUM(NEIL_CNT) AS NEIL_CNT , SUM(PACKAGE_CNT) AS PACKAGE_CNT , SUM(PRVATE_CNT) AS PRVATE_CNT , SUM(NTN_CNT) AS NTN_CNT , SUM(UNIVA_CNT) AS UNIVA_CNT , SUM(CERTI_CNT) AS CERTI_CNT , DECODE(SUM(STG1_CNT), 0, 0, ROUND(SUM(STG4_FNSH_CNT) / SUM(STG1_CNT) * 100, 2)) AS FNSH_PERCENTAGE FROM (SELECT T1.CTPV_CD , T1.SGG_CD , T1.INST_NO , T1.INST_NM , T1.CASE_MNG_NO , T1.CASE_MNG_ODRNO , T1.TRPR_INFO_NO , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT + T1.STG2_FNSH_CNT + T1.STG2_FAILR_CNT + T1.STG3_FNSH_CNT + T1.STG3_FAILR_CNT + T1.STG4_FNSH_CNT + T1.STG4_FAILR_CNT = 0 THEN T1.STG1_CNT ELSE 0 END AS STG1_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT + T1.STG3_FNSH_CNT + T1.STG3_FAILR_CNT + T1.STG4_FNSH_CNT + T1.STG4_FAILR_CNT = 0 THEN T1.STG2_FNSH_CNT ELSE 0 END AS STG2_FNSH_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT + T1.STG3_FNSH_CNT + T1.STG3_FAILR_CNT + T1.STG4_FNSH_CNT + T1.STG4_FAILR_CNT = 0 THEN T1.STG2_FAILR_CNT ELSE 0 END AS STG2_FAILR_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT + T1.STG4_FNSH_CNT + T1.STG4_FAILR_CNT = 0 THEN T1.STG3_FNSH_CNT ELSE 0 END AS STG3_FNSH_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT + T1.STG4_FNSH_CNT + T1.STG4_FAILR_CNT = 0 THEN T1.STG3_FAILR_CNT ELSE 0 END AS STG3_FAILR_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT + UNIVA_CNT + CERTI_CNT = 0 THEN T1.STG4_FNSH_CNT ELSE 0 END AS STG4_FNSH_CNT , CASE WHEN FOUND_CNT + JOB_CNT + JOB_CNT2 + NEIL_CNT + PACKAGE_CNT + PRVATE_CNT + NTN_CNT +UNIVA_CNT + CERTI_CNT = 0 THEN T1.STG4_FAILR_CNT ELSE 0 END AS STG4_FAILR_CNT , T1.FOUND_CNT , T1.JOB_CNT , T1.JOB_CNT2 , T1.NEIL_CNT , T1.PACKAGE_CNT , T1.PRVATE_CNT , T1.NTN_CNT , T1.UNIVA_CNT , T1.CERTI_CNT FROM (SELECT E.CTPV_CD , E.SGG_CD , E.INST_NO , E.INST_NM , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , B.TRPR_INFO_NO , (SELECT COUNT(1) FROM AKA100 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND STG1_PTCPTN_STTS_SE_CD = '01') AS STG1_CNT , DECODE(A.STG2_FNSH_YMD, NULL, 0, 1) AS STG2_FNSH_CNT , DECODE(A.STG2_MDSTRM_FAILR_YMD, NULL, 0, 1) AS STG2_FAILR_CNT , DECODE(A.STG3_FNSH_YMD, NULL, 0, 1) AS STG3_FNSH_CNT , DECODE(A.STG3_MDSTRM_FAILR_YMD, NULL, 0, 1) AS STG3_FAILR_CNT , DECODE(A.STG4_FNSH_YMD, NULL, 0, 1) AS STG4_FNSH_CNT , DECODE(A.STG4_MDSTRM_FAILR_YMD, NULL, 0, 1) AS STG4_FAILR_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_MLSFC_SE_CD = '0203') AS FOUND_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD = '020101') AS JOB_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD = '020102') AS JOB_CNT2 , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD = '020402') AS NEIL_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD = '020403') AS PACKAGE_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD = '020404') AS NTN_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_SCLAS_SE_CD IN ('020405','020408')) AS PRVATE_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_MLSFC_SE_CD = '0108') AS UNIVA_CNT , (SELECT COUNT(1) FROM AKA130 WHERE CASE_MNG_NO = B.CASE_MNG_NO AND CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND UNT_TASKWK_SE_CD = B.UNT_TASKWK_SE_CD AND USE_YN = 'Y' AND OUTC_CN_MLSFC_SE_CD = '0202') AS CERTI_CNT FROM AKA100 A, SEB100 B, SEA200 C, SEB150 D, SAA000 E, SCA100 F WHERE A.CASE_MNG_NO = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO = B.CASE_MNG_ODRNO AND B.UNT_TASKWK_SE_CD = 'U03' AND B.TRPR_INFO_NO = C.TRPR_INFO_NO AND A.CASE_MNG_NO = D.CASE_MNG_NO AND A.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO AND D.PCHPRS_YN = 'Y' AND D.CASE_PIC_NO = F.ENFSN_NO AND F.OGDP_INST_NO = E.INST_NO /* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND B.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND E.INST_NO = #{INST_NO}
AND C.SXDC_SE_CD = #{SXDC_SE_CD}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
AND ( 1=2 /* 청소년상태 체크를 모두 해제 한 경우 데이터 안나오게 하기 위한 false 조건 */
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_0}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_1}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_2}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_3}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_4}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_5}||'%'
) ) T1 ) TT1 , (SELECT DISTINCT T2.CTPV_SE_CD, T2.CTPV_NM FROM SAA020 T2) TT2 , (SELECT DISTINCT T3.SGG_CD, T3.SGG_NM FROM SAA020 T3) TT3 WHERE TT1.CTPV_CD = TT2.CTPV_SE_CD AND TT1.SGG_CD = TT3.SGG_CD GROUP BY TT1.CTPV_CD , TT1.INST_NO , TT1.INST_NM , TT2.CTPV_NM , TT3.SGG_CD , TT3.SGG_NM

/* isry.drmgs.stats.mapper.StatsDrmgsMapper.selectMeditationStats 학업숙려제통계 */ SELECT TT1.CTPV_CD , TT2.CTPV_NM , TT3.SGG_CD , TT3.SGG_NM , TT1.INST_NO , TT1.INST_NM , COUNT(DISTINCT TT1.M_TRPR) AS M_TRPR_CNT , COUNT(DISTINCT TT1.F_TRPR) AS F_TRPR_CNT , SUM(TT1.M_CASE_CNT) AS M_CASE_CNT , SUM(TT1.F_CASE_CNT) AS F_CASE_CNT , SUM(TT1.M0101) AS M0101_CNT , SUM(TT1.F0101) AS F0101_CNT , SUM(TT1.M0102) AS M0102_CNT , SUM(TT1.F0102) AS F0102_CNT , SUM(TT1.M0103) AS M0103_CNT , SUM(TT1.F0103) AS F0103_CNT , SUM(TT1.M0104) AS M0104_CNT , SUM(TT1.F0104) AS F0104_CNT , SUM(TT1.M0105) AS M0105_CNT , SUM(TT1.F0105) AS F0105_CNT , SUM(TT1.M0106) AS M0106_CNT , SUM(TT1.F0106) AS F0106_CNT , SUM(TT1.M0201) AS M0201_CNT , SUM(TT1.F0201) AS F0201_CNT , SUM(TT1.M0202) AS M0202_CNT , SUM(TT1.F0202) AS F0202_CNT , SUM(TT1.M0203) AS M0203_CNT , SUM(TT1.F0203) AS F0203_CNT , SUM(TT1.M0204) AS M0204_CNT , SUM(TT1.F0204) AS F0204_CNT , SUM(TT1.M0205) AS M0205_CNT , SUM(TT1.F0205) AS F0205_CNT , SUM(TT1.M0206) AS M0206_CNT , SUM(TT1.F0206) AS F0206_CNT , SUM(TT1.COL0300) AS COL0300_CNT , SUM(TT1.COL0400) AS COL0400_CNT , SUM(TT1.COL0500) AS COL0500_CNT FROM ( SELECT T1.CTPV_CD , T1.INST_NO , T1.INST_NM , T1.SGG_CD , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.SXDC_SE_CD||T1.TRPR_INFO_NO END AS M_TRPR , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.SXDC_SE_CD||T1.TRPR_INFO_NO END AS F_TRPR , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN 1 ELSE 0 END AS M_CASE_CNT , CASE WHEN T1.SXDC_SE_CD = 'F' THEN 1 ELSE 0 END AS F_CASE_CNT , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0101 ELSE 0 END AS M0101 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0101 ELSE 0 END AS F0101 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0102 ELSE 0 END AS M0102 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0102 ELSE 0 END AS F0102 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0103 ELSE 0 END AS M0103 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0103 ELSE 0 END AS F0103 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0104 ELSE 0 END AS M0104 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0104 ELSE 0 END AS F0104 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0105 ELSE 0 END AS M0105 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0105 ELSE 0 END AS F0105 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0106 ELSE 0 END AS M0106 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0106 ELSE 0 END AS F0106 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0201 ELSE 0 END AS M0201 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0201 ELSE 0 END AS F0201 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0202 ELSE 0 END AS M0202 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0202 ELSE 0 END AS F0202 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0203 ELSE 0 END AS M0203 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0203 ELSE 0 END AS F0203 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0204 ELSE 0 END AS M0204 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0204 ELSE 0 END AS F0204 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0205 ELSE 0 END AS M0205 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0205 ELSE 0 END AS F0205 , CASE WHEN T1.SXDC_SE_CD = 'M' OR T1.SXDC_SE_CD = 'X' THEN T1.COL0206 ELSE 0 END AS M0206 , CASE WHEN T1.SXDC_SE_CD = 'F' THEN T1.COL0206 ELSE 0 END AS F0206 , T1.COL0300 , T1.COL0400 , T1.COL0500 FROM ( SELECT E.CTPV_CD , E.INST_NO , E.INST_NM , E.SGG_CD , A.CASE_MNG_NO , A.CASE_MNG_ODRNO , B.TRPR_INFO_NO , C.SXDC_SE_CD , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '01', 1, 0) ,0) AS COL0101 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '02', 1, 0) ,0) AS COL0102 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '03', 1, 0) ,0) AS COL0103 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '04', 1, 0) ,0) AS COL0104 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '05', 1, 0) ,0) AS COL0105 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '01', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '06', 1, 0) ,0) AS COL0106 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '01', 1, 0) ,0) AS COL0201 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '02', 1, 0) ,0) AS COL0202 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '03', 1, 0) ,0) AS COL0203 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '04', 1, 0) ,0) AS COL0204 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '05', 1, 0) ,0) AS COL0205 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '02', DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_END_AFTR_SPRT_SE_CD, '06', 1, 0) ,0) AS COL0206 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '03', 1, 0) AS COL0300 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, '04', 1, 0) AS COL0400 , DECODE(A.SCHULW_DSCNTC_CNSDRA_TRGT_DSCSN_RESULT_SE_CD, NULL, 1, 0) AS COL0500 FROM AKA100 A, SEB100 B, SEA200 C, SEB150 D, SAA000 E WHERE A.CASE_MNG_NO(+) = B.CASE_MNG_NO AND A.CASE_MNG_ODRNO(+) = B.CASE_MNG_ODRNO AND B.UNT_TASKWK_SE_CD = 'U03' AND B.TRPR_INFO_NO = C.TRPR_INFO_NO AND B.CASE_MNG_NO = D.CASE_MNG_NO AND B.CASE_MNG_ODRNO = D.CASE_MNG_ODRNO AND D.PCHPRS_YN = 'Y' AND D.PIC_INST_NO = E.INST_NO AND B.YNGBGS_SE_NO LIKE '%02%' /* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리시작*/
/* 20230220_강화영_권한 쿼리 최종변경사항 수정_권한쿼리종료*/
AND B.CASE_BGNG_YMD BETWEEN #{SRT_DT} AND #{END_DT}
AND E.CTPV_CD = #{CTPV_CD}
AND E.SGG_CD = #{SGG_CD}
AND E.INST_NO = #{INST_NO}
AND C.SXDC_SE_CD = #{SXDC_SE_CD}
-- 만 6세 이하 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) <= 6
-- 만 7~12세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 7 AND 12
-- 만 13~15세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 13 AND 15
-- 만 16~18세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 16 AND 18
-- 만 19~24세 AND TRUNC(MONTHS_BETWEEN(SYSDATE,C.TRPR_BRTH_YMD)/12,0) BETWEEN 19 AND 24
-- 연령 미확인 AND C.TRPR_BRTH_YMD IS NULL
-- 연령 기타
AND ( 1=2 /* 청소년상태 체크를 모두 해제 한 경우 데이터 안나오게 하기 위한 false 조건 */
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_0}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_1}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_2}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_3}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_4}||'%'
OR B.YNGBGS_SE_NO LIKE '%'||#{YNGBGS_5}||'%'
) ) T1 ) TT1 , (SELECT DISTINCT T2.CTPV_SE_CD, T2.CTPV_NM FROM SAA020 T2) TT2 , (SELECT DISTINCT T3.SGG_CD, T3.SGG_NM FROM SAA020 T3) TT3 WHERE TT1.CTPV_CD = TT2.CTPV_SE_CD AND TT1.SGG_CD = TT3.SGG_CD GROUP BY TT1.CTPV_CD , TT1.INST_NO , TT1.INST_NM , TT2.CTPV_NM , TT3.SGG_CD , TT3.SGG_NM
